mapper.select:
SELECT ol.* FROM operation_log ol
LEFT JOIN app_user u ON ol.user_id = u.id


        u.company_id = #{companyId}


        AND ol.operation = #{operation}


        AND ol.target_type = #{targetType}


        AND ol.target_id = #{targetId}


        AND ol.target_id IN (SELECT id FROM cylinder WHERE code = #{cylinderCode})


        AND ol.ip LIKE CONCAT('%', #{ip}, '%')


        AND ol.create_time >= #{startTime}


        AND ol.create_time <= #{endTime}


ORDER BY ol.create_time DESC
